%&\implies \frac{\partial p_{s+t}(1) - p_s(1)}{\partial t} = \lambda. ~~\text{(by independence and stationarity)}
\end{aligned}
$$
-->

Note that 

$$
\begin{aligned}
\Prob(N(t+h) - N(t) = 0) &= \Prob(N(h) - N(0) = 0) ~~\text{(by D1(2))}\\
&= \Prob(N(h) = 0) = p_h(0) ~~\text{(by D1(3))}
\end{aligned}
$$

Therefore,

$$
\begin{aligned}
\Prob(T_1 > t+h) &= \Prob(T_1 > t) \Prob(T_1 > t+h | T_1 > t)\\
&= \Prob(T_1 > t) \Prob(N(t+h) - N(t) = 0)\\
&= \Prob(T_1 > t) p_h(0)\\
&= \Prob(T_1 > t) (1 - \lambda h + o(h))
\end{aligned}
$$

$$
\begin{aligned}
\implies \lim_{h \to 0} \frac{\Prob(T_1 > t+h) - \Prob(T_1 > t)}{h} &= \lim_{h \to 0} \frac{\Prob(T_1 > t)[-\lambda h+ o(h)]}{h}\\
\implies \frac{\partial \Prob(T_1 > t)}{\partial t} &= -\lambda \Prob(T_1 > t)\\
\implies \Prob(T_1 > t) &= e^{-\lambda t}\\
\implies \Prob(T_1 \leq t) &= 1 - e^{-\lambda t} \tag{4}
\end{aligned}
$$

That is, the time of first arrival is exponentially distributed with rate $\lambda$.

Now, 

$$
\begin{aligned}
p_t(1) &= \Prob(N(t) = 1) = \int_0^t \Prob(N(s) = 1) \Prob(N(t) - N(s) = 0) \mathrm{d}s ~~\text{by D1(2)}\\
&= \int_0^t \lambda e^{-\lambda s} 
